// ============================================================
// Internal fetch helper
// ============================================================
async function apiGet(url: string) {
 const resp = await fetch(url, {
 headers: { Accept: 'application/json', 'X-UserToken': (window as any).g_ck || '' },
 })
 if (!resp.ok) return null
 return resp.json()
}

// ============================================================
// SERVER API CALLS (replaces 30-50+ client-side calls)
// ============================================================

/**
 * Run a fresh CSDM compliance scan via the server-side REST API.
 * Single request replaces all individual Stats API + Table API calls.
 */
export async function fetchServerScan(): Promise<any> {
 const data = await apiGet('/api/x_147805_csdmviz/csdm_scan/run')
 // Scripted REST API wraps body in result
 if (data && data.result) return data.result
 return data
}

/**
 * Fetch the most recent cached scan result from the server.
 * Returns null if no cached scan exists.
 */
export async function fetchLatestScan(): Promise<any> {
 const data = await apiGet('/api/x_147805_csdmviz/csdm_scan/latest')
 if (data && data.result) return data.result
 return data
}

// ============================================================
// SAVE SCAN RESULT (kept for backward compatibility)
// ============================================================
export async function saveScanResult(scanData: any): Promise<string | null> {
 const dims = scanData.dimensions
 const dimSummary = Object.values(dims)
 .map((d: any) => `${d.label}: ${d.score}%`)
 .join(' | ')
 const summary = `Overall: ${scanData.score}% | ${dimSummary}`

 const record = {
 scan_name: 'CSDM 5.0 Scan - ' + new Date().toLocaleDateString(),
 scan_date: new Date().toISOString().replace('T', ' ').substring(0, 19),
 status: 'completed',
 total_classes: scanData.population.summary.totalClasses,
 populated_classes: scanData.population.summary.populatedClasses,
 risk_count: scanData.risks.summary.total,
 relationship_issues: scanData.relationships.stats.non_recommended || 0,
 overall_score: scanData.score,
 scan_data: JSON.stringify(scanData),
 summary: summary,
 }

 try {
 const resp = await fetch('/api/now/table/x_147805_csdmviz_scan_result', {
 method: 'POST',
 headers: {
 Accept: 'application/json',
 'Content-Type': 'application/json',
 'X-UserToken': (window as any).g_ck || '',
 },
 body: JSON.stringify(record),
 })
 if (resp.ok) {
 const data = await resp.json()
 return data?.result?.sys_id || null
 }
 } catch {
 /* ignore */
 }
 return null
}

export async function executeLiveQuery(table: string, query: string, limit: number, fields: string[]) {
 const fieldsStr = fields.join(',')
 const url = `/api/now/table/${table}?sysparm_query=${encodeURIComponent(query)}&sysparm_limit=${limit}&sysparm_fields=${fieldsStr}&sysparm_display_value=true`
 const data = await apiGet(url)
 if (data?.result) return { table, count: data.result.length, records: data.result }
 return { table, count: 0, records: [] }
}
